SELECT c.name, c.artist, c.isPromo
FROM cards c
JOIN (
  SELECT uuid, COUNT(*) AS cnt
  FROM rulings
  GROUP BY uuid
) rc ON c.uuid = rc.uuid
WHERE rc.cnt = (
  SELECT MAX(cnt) FROM (SELECT uuid, COUNT(*) AS cnt FROM rulings GROUP BY uuid)
);

